_a4:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n/// @description  Enemy triangle shader — black fill + white outline, sharp edges, organic wobble\n\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nuniform float u_time;\nuniform vec2 u_texel;\n\nvoid main()\n{\n    vec2 tc = v_vTexcoord;\n    \n    // Organic multi-frequency wobble — makes triangles shift/deform continuously\n    float w1 = sin(tc.y * 30.0 + u_time * 1.5);\n    float w2 = sin(tc.x * 20.0 + tc.y * 15.0 + u_time * 2.0);\n    float w3 = cos(tc.x * 25.0 + u_time * 1.8);\n    float w4 = cos(tc.x * 12.0 + tc.y * 18.0 + u_time * 2.2);\n    vec2 wobble = vec2(w1 * 0.3 + w2 * 0.3, w3 * 0.3 + w4 * 0.3) * u_texel * 6.0;\n    \n    // Re-sample at wobbled position for the 'moving triangles' effect\n    float a = texture2D(gm_BaseTexture, tc + wobble).a;\n    \n    // Sharp fill threshold (no blur — keeps crisp triangle edges)\n    if (a > 0.5) {\n        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);\n        return;\n    }\n    \n    // Thin 8-tap edge detection at wobbled + static position for white outline\n    float max_a = 0.0;\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2( 2.0,  0.0) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2(-2.0,  0.0) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2( 0.0,  2.0) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2( 0.0, -2.0) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2( 1.5,  1.5) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2(-1.5,  1.5) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2( 1.5, -1.5) * u_texel).a);\n    max_a = max(max_a, texture2D(gm_BaseTexture, tc + wobble + vec2(-1.5, -1.5) * u_texel).a);\n    \n    if (max_a > 0.1) {\n        gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);\n    } else {\n        gl_FragColor = vec4(0.0);\n    }\n}\n",
