_a4:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nuniform float u_strength; // positive = barrel distortion (bulge)\n\nvoid main()\n{\n    // Map uv to [-1, 1]\n    vec2 p = v_vTexcoord * 2.0 - 1.0;\n    \n    // Calculate distance from center\n    float r = length(p);\n    \n    // Apply barrel distortion formula (simplified brown-conrady)\n    float f = 1.0 + u_strength * r * r;\n    \n    // Distort coordinates\n    vec2 distorted_p = p * f;\n    \n    // Map back to [0, 1]\n    vec2 final_uv = (distorted_p + 1.0) * 0.5;\n    \n    // Sample texture or render black if out of bounds\n    if (final_uv.x < 0.0 || final_uv.x > 1.0 || final_uv.y < 0.0 || final_uv.y > 1.0) {\n        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);\n    } else {\n        gl_FragColor = v_vColour * texture2D(gm_BaseTexture, final_uv);\n    }\n}\n",
